// Baut aus den Data Tables Stellen, Kriterien und Leitfaden die Bewertungsgrundlage für den Analyse-Prompt.
const d = $('Daten extrahieren').first().json;
const stelle = $('Stelle laden').first().json;
if (!stelle.assistantId) {
  throw new Error('Keine Stelle für Assistant-ID "' + d.assistantId + '" in der Tabelle „Stellen“ gefunden (Call ' + d.callId + ').');
}

const zahl = (v) => parseFloat(String(v ?? '').replace('%', '').replace(',', '.'));
const liste = (text) => String(text ?? '').split(/\n|;/).map((s) => s.trim()).filter(Boolean);
const nachPosition = (a, b) => (Number(a.position) || 0) - (Number(b.position) || 0);

// Standardwerte, wenn in der UI nichts eingetragen ist.
const STANDARD_SKALA = {
  1: 'Deutlich unter der Erwartung an die Stelle.',
  2: 'Unter der Erwartung, mit deutlichen Lücken.',
  3: 'Erfüllt die Erwartung an die Stelle.',
  4: 'Über der Erwartung.',
  5: 'Herausragend, deutlich über der Erwartung.',
};
const STANDARD_EINLADEN_AB = 70;
const STANDARD_ABSAGE_UNTER = 45;

// Kriterien: Skala aus den gefüllten Stufen score1..score5. Keine gefüllt -> Standardskala 1–5,
// einzelne Lücken innerhalb der Skala -> Standardtext der Stufe.
const roh = $('Kriterien laden').all().map((i) => i.json).filter((r) => r.kriterium).sort(nachPosition).map((r) => {
  const gefuellt = [1, 2, 3, 4, 5]
    .map((wert) => ({ wert, text: String(r['score' + wert] ?? '').trim() }))
    .filter((s) => s.text);
  let stufen;
  if (!gefuellt.length) {
    stufen = Object.entries(STANDARD_SKALA).map(([wert, text]) => ({ wert: Number(wert), text }));
  } else {
    const werte = gefuellt.map((s) => s.wert);
    stufen = [];
    for (let w = Math.min(...werte); w <= Math.max(...werte); w++) {
      stufen.push(gefuellt.find((s) => s.wert === w) ?? { wert: w, text: STANDARD_SKALA[w] ?? 'Zwischenstufe.' });
    }
  }
  const gewicht = zahl(r.gewicht);
  return {
    name: String(r.kriterium).trim(),
    gewicht: gewicht > 0 ? gewicht : null,
    bewertet: String(r.beschreibung ?? '').trim() || String(r.kriterium).trim(),
    stufen,
    min: stufen[0].wert,
    max: stufen[stufen.length - 1].wert,
  };
});
// Leeres Gewicht -> Durchschnitt der eingetragenen Gewichte (alle leer -> gleich gewichtet).
const eingetragen = roh.filter((k) => k.gewicht !== null).map((k) => k.gewicht);
const standardGewicht = eingetragen.length ? eingetragen.reduce((a, b) => a + b, 0) / eingetragen.length : 1;
const kriterien = roh.map((k) => ({ ...k, gewicht: k.gewicht ?? standardGewicht }));
if (!kriterien.length) {
  throw new Error('Keine Bewertungskriterien für Assistant-ID "' + d.assistantId + '" in der Tabelle „Kriterien“ gefunden.');
}

const leitfaden = $('Leitfaden laden').all().map((i) => i.json).filter((r) => r.frage).sort(nachPosition);

const gewichtSumme = kriterien.reduce((s, k) => s + k.gewicht, 0) || 1;

const teile = [
  'Stelle: ' + stelle.stelle,
  'Unternehmen: ' + (stelle.unternehmen ?? ''),
  'Aufgaben:\n' + liste(stelle.aufgaben).map((a) => '- ' + a).join('\n'),
  'Anforderungen:\n' + liste(stelle.anforderungen).map((a) => '- ' + a).join('\n'),
  'Bewertungskriterien (jedes genau einmal bewerten, Name exakt übernehmen):\n' + kriterien.map((k, i) =>
    (i + 1) + '. ' + k.name + ' (Gewicht ' + Math.round((k.gewicht / gewichtSumme) * 100) + ' %, Skala ' + k.min + ' bis ' + k.max + ')\n'
    + '   Bewertet: ' + k.bewertet + '\n'
    + k.stufen.map((s) => '   ' + s.wert + ' = ' + s.text).join('\n')
  ).join('\n'),
  'Leitfaden des Interviews (welche Frage welches Kriterium prüft):\n' + leitfaden.map((l, i) =>
    (i + 1) + '. ' + l.thema + ': ' + l.frage + (l.kriterium ? ' → ' + l.kriterium : '')
  ).join('\n'),
];

return [{ json: {
  ...d,
  stelle: stelle.stelle,
  bewertungsgrundlage: teile.join('\n\n'),
  konfig: {
    kriterien: kriterien.map(({ name, gewicht, min, max }) => ({ name, gewicht, min, max })),
    einladenAb: Number.isFinite(zahl(stelle.einladenAb)) ? zahl(stelle.einladenAb) : STANDARD_EINLADEN_AB,
    absageUnter: Number.isFinite(zahl(stelle.absageUnter)) ? zahl(stelle.absageUnter) : STANDARD_ABSAGE_UNTER,
  },
} }];

