// Ergebnis der KI-Analyse + Regeln der Stelle -> Bewerberprotokoll für UI und Slack.
const p = $json.output;
const g = $('Bewertungsgrundlage bauen').item.json;
const konfig = g.konfig;
const norm = (s) => String(s ?? '').trim().toLowerCase();

// KI-Bewertung den Kriterien der Stelle zuordnen.
const bewertungen = konfig.kriterien.map((k) => {
  const b = (p.bewertung ?? []).find((x) => norm(x.kriterium) === norm(k.name)) ?? {};
  const gueltig = b.beurteilbar !== false && Number.isFinite(b.score) && b.score >= k.min && b.score <= k.max;
  return { ...k, score: gueltig ? b.score : null, begruendung: b.begruendung ?? 'Nicht bewertet.', zitat: b.zitat ?? '' };
});

// Gesamtscore in Prozent: jede Skala auf 0–100 % normiert, dann nach Gewicht gemittelt.
let summe = 0;
let gewichte = 0;
for (const b of bewertungen) {
  if (b.score === null || b.gewicht <= 0) continue;
  const anteil = b.max > b.min ? (b.score - b.min) / (b.max - b.min) : 1;
  summe += anteil * b.gewicht;
  gewichte += b.gewicht;
}
const vollstaendig = p.status === 'vollständig';
const gesamt = vollstaendig && gewichte > 0 ? Math.round((summe / gewichte) * 100) : null;

// Empfehlung nach festen Regeln (Schwellen der Stelle).
const regeln = [];
let empfehlung;
if (!vollstaendig) {
  empfehlung = 'Prüfen';
  regeln.push('Gespräch ' + p.status + ' → Prüfen');
} else if (gesamt === null) {
  empfehlung = 'Prüfen';
  regeln.push('Kein Kriterium beurteilbar → Prüfen');
} else if (gesamt >= konfig.einladenAb) {
  empfehlung = 'Einladen';
  regeln.push('Gesamtscore ' + gesamt + ' % ≥ ' + konfig.einladenAb + ' % → Einladen');
} else if (gesamt < konfig.absageUnter) {
  empfehlung = 'Absage';
  regeln.push('Gesamtscore ' + gesamt + ' % < ' + konfig.absageUnter + ' % → Absage');
} else {
  empfehlung = 'Prüfen';
  regeln.push('Gesamtscore ' + gesamt + ' % zwischen ' + konfig.absageUnter + ' % und ' + konfig.einladenAb + ' % → Prüfen');
}
if (empfehlung === 'Einladen' && p.schwerwiegende_red_flag) {
  empfehlung = 'Prüfen';
  regeln.push('Schwerwiegende Red Flag → höchstens Prüfen');
}

const liste = (arr) => (arr ?? []).map((x) => '• ' + x).join('\n');
const scoreText = (b) => (b.score === null ? '–' : b.score + '/' + b.max);

const row = {
  'Call-ID': g.callId,
  'Datum': g.datum,
  'Stelle': g.stelle,
  'Name': p.name,
  'Dauer (Min)': g.dauerMin,
  'Gesprächsende': g.endedReason,
  'Vollständig': vollstaendig ? 'Ja' : 'Nein – ' + p.status,
  'Empfehlung': empfehlung,
  'Gesamtscore (%)': gesamt ?? '',
  'Scores': bewertungen.map((b) => b.name + ' ' + scoreText(b)).join(' · '),
  'Zusammenfassung': p.zusammenfassung,
  'Stärken': liste(p.staerken),
  'Schwächen / Red Flags': liste(p.schwaechen_red_flags),
  'Begründungen': bewertungen.map((b) => b.name + ' (' + scoreText(b) + '): ' + b.begruendung + (b.zitat ? ' „' + b.zitat + '“' : '')).join('\n')
    + '\n\nEmpfehlung: ' + regeln.join('; ') + '\nEinschätzung: ' + (p.einschaetzung ?? ''),
  'Gehaltsvorstellung': p.eckdaten?.gehaltsvorstellung ?? '',
  'Verfügbarkeit': p.eckdaten?.verfuegbarkeit ?? '',
  'Startdatum': p.eckdaten?.startdatum ?? '',
  'Offene Punkte': liste(p.offene_punkte),
  'Aufnahme': g.aufnahmeUrl,
  'Transkript': g.transkript ?? '',
};

// Strukturierte Fassung für die UI (Tabelle „Protokolle“, Spalte protokoll).
const details = {
  name: p.name,
  stelle: g.stelle,
  datum: g.datum,
  dauerMin: g.dauerMin,
  gespraechsende: g.endedReason,
  status: p.status,
  empfehlung,
  gesamtscore: gesamt,
  regeln,
  zusammenfassung: p.zusammenfassung ?? '',
  einschaetzung: p.einschaetzung ?? '',
  bewertungen: bewertungen.map(({ name, gewicht, min, max, score, begruendung, zitat }) => ({ name, gewicht, min, max, score, begruendung, zitat })),
  staerken: p.staerken ?? [],
  schwaechen: p.schwaechen_red_flags ?? [],
  eckdaten: p.eckdaten ?? {},
  offenePunkte: p.offene_punkte ?? [],
};

return { json: { ...row, protokollJson: JSON.stringify(details) } };

// Die Nachricht enthält das vollständige Bewerberprotokoll (wie in der UI), das Transkript folgt im Thread.
// Block Kit, rein informativ, ohne Buttons (REQ-5.2, REQ-5.3).
const r = $('Protokoll aufbereiten').item.json;

// Slack mrkdwn verlangt escapte Sonderzeichen.
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Slack-Limits: 3000 Zeichen pro Textblock, 2000 pro Feld, 50 Blöcke pro Nachricht.
const kurz = (t, max) => (t.length > max ? t.slice(0, max - 2) + ' …' : t);
const feld = (name, wert) => ({ type: 'mrkdwn', text: kurz('*' + name + '*\n' + (esc(wert) || '–'), 2000) });
// Langen Text an Zeilengrenzen auf mehrere Abschnitte verteilen.
const abschnitte = (titel, text) => {
  const teile = [];
  let aktuell = '*' + titel + '*';
  for (const zeile of esc(text).split('\n')) {
    const z = kurz(zeile, 2900);
    if (aktuell.length + 1 + z.length > 2900) {
      teile.push(aktuell);
      aktuell = z;
    } else {
      aktuell += '\n' + z;
    }
  }
  teile.push(aktuell);
  return teile.filter((t) => t.trim()).map((t) => ({ type: 'section', text: { type: 'mrkdwn', text: t } }));
};

// Unvollständige Gespräche und fehlende Einwilligung werden nicht normal bewertet (REQ-4.7).
const ICON = { Einladen: '🟢', 'Prüfen': '🟡', Absage: '🔴' };
let titel;
if (r['Vollständig'] === 'Ja') {
  titel = (ICON[r.Empfehlung] ?? '⚪') + ' ' + r.Empfehlung + ' – ' + r.Name;
} else if (r['Vollständig'].includes('keine Einwilligung')) {
  titel = '⚪ Keine Einwilligung – ' + r.Name;
} else {
  titel = '⚪ ' + r.Empfehlung + ' (unvollständig) – ' + r.Name;
}
const gesamt = r['Gesamtscore (%)'] === '' ? '–' : r['Gesamtscore (%)'] + ' %';

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: kurz(titel, 150), emoji: true } },
  { type: 'section', fields: [
    feld('Stelle', r.Stelle),
    { type: 'mrkdwn', text: '*Gesamtscore*\n' + gesamt },
    feld('Datum', r.Datum),
    { type: 'mrkdwn', text: '*Dauer*\n' + String(r['Dauer (Min)']).replace('.', ',') + ' Min.' },
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: kurz('*Zusammenfassung*\n' + esc(r.Zusammenfassung), 3000) } },
  { type: 'section', fields: [feld('Stärken', r['Stärken']), feld('Schwächen / Red Flags', r['Schwächen / Red Flags'])] },
  { type: 'section', text: { type: 'mrkdwn', text: kurz('*Scores*  ' + esc(r.Scores), 3000) } },
  ...abschnitte('Begründungen und Empfehlungsregel', r['Begründungen']),
  { type: 'section', fields: [
    feld('Gehaltsvorstellung', r.Gehaltsvorstellung),
    feld('Verfügbarkeit', r['Verfügbarkeit']),
    feld('Startdatum', r.Startdatum),
    feld('Gesprächsende', r['Gesprächsende']),
  ] },
];
if (r['Offene Punkte']) blocks.push(...abschnitte('Offene Punkte für HR', r['Offene Punkte']));
const kontext = [
  r.Aufnahme ? '<' + r.Aufnahme + '|Aufnahme anhören>' : 'Keine Aufnahme',
  'Transkript im Thread',
  'Call-ID ' + esc(r['Call-ID']),
  'Empfehlung nach den Regeln der Stelle – die Entscheidung trifft HR.',
].join('  ·  ');
blocks.push({ type: 'divider' }, { type: 'context', elements: [{ type: 'mrkdwn', text: kurz(kontext, 3000) }] });
const fertig = blocks.length > 50 ? [...blocks.slice(0, 48), ...blocks.slice(-2)] : blocks;

return { json: { slackBlocks: JSON.stringify({ blocks: fertig }), slackText: titel } };

// Transkript als Antworten im Thread der Protokoll-Nachricht (Slack empfiehlt höchstens 4.000 Zeichen pro Nachricht).
const ts = $json.message_timestamp ?? $json.message?.ts;
if (!ts) throw new Error('Slack hat keinen Zeitstempel der Protokoll-Nachricht geliefert.');
const text = String($('Protokoll aufbereiten').first().json['Transkript'] ?? '').trim() || 'Kein Transkript vorhanden.';

const esc = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const MAX = 3500;
const zeilen = esc(text).split('\n').flatMap((z) => (z.length > MAX ? z.match(new RegExp('.{1,' + MAX + '}', 'g')) : [z]));
const teile = [];
let aktuell = '';
for (const z of zeilen) {
  if (aktuell && aktuell.length + 1 + z.length > MAX) {
    teile.push(aktuell);
    aktuell = z;
  } else {
    aktuell = aktuell ? aktuell + '\n' + z : z;
  }
}
if (aktuell) teile.push(aktuell);

return teile.map((t, i) => ({ json: {
  ts,
  text: '*Transkript' + (teile.length > 1 ? ' (' + (i + 1) + '/' + teile.length + ')' : '') + '*\n' + t,
} }));

// Live-Status aus Vapis status-update: „läuft“ beim Start, „beendet“ beim Auflegen.
// Ein Protokoll, das schon erstellt wird oder fertig ist, wird nicht zurückgesetzt.
const m = $('Vapi Webhook').first().json.body?.message ?? {};
const callId = m.call?.id;
if (!callId) return [];

const vorhanden = $input.first()?.json ?? {};
const alt = vorhanden.status;
const jetzt = new Date(Number(m.timestamp) || Date.now()).toISOString();
const basis = { callId, assistantId: m.call?.assistantId ?? m.assistant?.id ?? vorhanden.assistantId ?? '' };

if (m.status === 'in-progress') {
  if (alt) return [];
  return [{ json: { ...basis, status: 'laeuft', startedAt: m.call?.startedAt ?? jetzt, endedAt: null } }];
}
if (m.status === 'ended') {
  if (alt && alt !== 'laeuft') return [];
  return [{ json: { ...basis, status: 'beendet', startedAt: vorhanden.startedAt ?? m.call?.startedAt ?? null, endedAt: m.call?.endedAt ?? jetzt } }];
}
return [];
